from collections import Counter
def masks(g,sep):
    rs={i for i,row in enumerate(g) if all(v==sep for v in row)}
    cs={j for j in range(len(g[0])) if all(row[j]==sep for row in g)}
    R=groups(rs,len(g)); C=groups(cs,len(g[0]))
    return R,C
def poscount(inp, sep, marker):
    R,C=masks(inp,sep)
    cnt=Counter()
    for bi,BR in enumerate(R):
        for bj,BC in enumerate(C):
            for i in BR:
                for j in BC:
                    if inp[i][j]==marker: cnt[(i-BR[0], j-BC[0])]+=1
    return cnt
